-- ============================================================================
-- HiWS — Hiswill Web Stack. The schema.
--
-- Create the database and load this file with:
--     mysql -uroot -proot -e "CREATE DATABASE IF NOT EXISTS hiws CHARACTER SET utf8mb4"
--     mysql -uroot -proot hiws < database.sql
--
-- WARNING: both tables are DROPped first, so importing this file destroys every
-- existing row. It is how the database is created from nothing, and how a
-- development copy is reset. It is not a migration and there is no runner.
--
-- The icon column holds a Font Awesome 6 name WITHOUT the style prefix, so
-- 'fa-screwdriver-wrench' renders as <i class="fa-solid fa-screwdriver-wrench">.
-- A value beginning 'fa-brands' is used as given, for brand marks.
-- ============================================================================

SET NAMES utf8mb4;

DROP TABLE IF EXISTS `tools`;
DROP TABLE IF EXISTS `projects`;

-- ----------------------------------------------------------------------------
-- projects — the cards on the home page. status = 0 hides a row without
-- deleting it, which is how a project still being built stays out of sight.
-- ----------------------------------------------------------------------------
CREATE TABLE `projects` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Untitled',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `url` tinytext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `icon` tinytext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `status` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `title` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `projects` VALUES (1,'Web Tools','A drawer of small online utilities for everyday jobs — domains, networking, security, colours, code and more. No sign-up, no cost.','tools','fa-screwdriver-wrench',1);
INSERT INTO `projects` VALUES (2,'Online Bible','Read the Bible online, anywhere, with nothing to install. Search a passage, open it by book and chapter, and read it on a clean, quiet page.','bible','fa-book-bible',1);
INSERT INTO `projects` VALUES (3,'Simple File Manager','A small web file manager: browse a folder, then upload, download, rename and delete, all from the browser. Handy when a phone is all you have.','sifm','fa-folder-tree',1);

-- ----------------------------------------------------------------------------
-- tools — every tool the tools project offers, with the explainer text that
-- sits under the form. `url` is the page name, so a row becomes /tools/<url>.
-- ----------------------------------------------------------------------------
CREATE TABLE `tools` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Untitled',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `keywords` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `url` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'question-circle',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Uncategorized',
  `status` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `title` (`title`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `tools` VALUES ('1','DNS Lookup','Lookup all the DNS Lookup records of a particular domain name','','## What is DNS?\r\n**DNS (Domain Name System)** is a system that translates human-readable domain names (like `www.example.com`) into IP addresses (like `192.0.2.1`) that computers use to identify each other on the network. It functions like a phone book for the internet, allowing users to access websites using easy-to-remember names instead of numerical addresses.\r\n\n### Key Components of DNS:\r\n\n1. **Domain Names**: Structured hierarchically, consisting of levels separated by dots. For example, in `www.example.com`, "com" is the top-level domain (TLD), "example" is the second-level domain, and "www" is a subdomain.\r\n\n2. **DNS Records**: Information stored in DNS servers, including:\r\n\n   - **A Record**: Maps a domain to an IPv4 address.\r\n\n   - **AAAA Record**: Maps a domain to an IPv6 address.\r\n\n   - **CNAME Record**: Alias of one domain to another.\r\n\n3. **DNS Servers**: \r\n\n   - **Recursive Resolvers**: Handle the initial request from the client and query other DNS servers to find the answer.\r\n\n   - **Root Name Servers**: The top-level servers that direct queries to appropriate TLD servers.\r\n\n   - **TLD Name Servers**: Manage the next level of the domain hierarchy (e.g., `.com`, `.org`).\r\n\n   - **Authoritative Name Servers**: Provide the final answer for a specific domain.\r\n\n### How DNS Works:\r\n\n1. A user enters a domain name in their browser.\r\n\n2. The request is sent to a recursive resolver.\r\n\n3. If the resolver doesn\'t have the answer cached, it queries the root name server.\r\n\n4. The root server directs the resolver to a TLD server.\r\n\n5. The TLD server points to the authoritative name server for the domain.\r\n\n6. The authoritative name server provides the IP address, allowing the user\'s device to connect to the desired website.','dns-lookup','server','Network','1');
INSERT INTO `tools` VALUES ('2','IP Address Lookup','Lookup information associated to a certain IP Address','','## What is an IP address?\r\nAn IP address (Internet Protocol address) is a unique numerical label assigned to each device connected to a computer network that uses the Internet Protocol for communication. It serves two main functions: identifying the host or network interface and providing the location of the device in the network.\r\n\nThere are two types of IP addresses:\r\n\n1. **IPv4**: This is the most commonly used format, consisting of four sets of numbers ranging from 0 to 255, separated by periods (e.g., 192.168.1.1).\r\n\n2. **IPv6**: This is a newer format designed to replace IPv4, consisting of eight groups of four hexadecimal digits, separated by colons (e.g., 2001:0db8:85a3:0000:0000:8a2e:0370:7334).\r\n','ip-lookup','network-wired','Network','1');
INSERT INTO `tools` VALUES ('3','WHOIS Lookup','Lookup WHOIS information of a certain domain name','','## What is WHOIS?\r\n **WHOIS** is a query and response protocol used to obtain information about the ownership of a domain name or an IP address. It allows users to find details such as:\r\n\n- **Domain Registrant**: The person or organization that registered the domain.\r\n\n- **Contact Information**: Email addresses, phone numbers, and mailing addresses of the registrant.\r\n\n- **Domain Status**: Information about the registration status, expiration date, and name servers.\r\n\n- **Registrar Information**: The company that manages the domain registration.\r\n\nTo perform a WHOIS lookup, you can use various online WHOIS services or command-line tools. Keep in mind that due to privacy regulations (like GDPR), some registrant information may be redacted or unavailable.','whois','circle-question','Network','1');
INSERT INTO `tools` VALUES ('4','Phone Lookup','Lookup the information of a certain phone number','','','phone-lookup','phone','Miscellaneous','1');
INSERT INTO `tools` VALUES ('5','Word Lookup','Lookup the english meanings of a certain word','','','word-lookup','book','Miscellaneous','1');
INSERT INTO `tools` VALUES ('6','Currency Converter','Convert money from one currency to another quickly','','## What is currency?\r\n\n**Currency** refers to a system of money in general use within a particular country or economic context. It serves as a medium of exchange, a measure of value, and a store of value. Here are some key points about currency:\r\n\n### Types of Currency\r\n\n1. **Fiat Currency**: \r\n\n   - Government-issued money that is not backed by a physical commodity (like gold). Its value comes from the trust and stability of the issuing government (e.g., USD, EUR).\r\n\n2. **Commodity Currency**: \r\n\n   - Money that is backed by a physical commodity. Historically, currencies like gold or silver served this purpose.\r\n\n3. **Cryptocurrency**: \r\n\n   - A digital or virtual currency that uses cryptography for security and operates on decentralized networks (e.g., Bitcoin, Ethereum).\r\n\n### Functions of Currency\r\n\n1. **Medium of Exchange**: \r\n\n   - Facilitates transactions for goods and services.\r\n\n2. **Unit of Account**: \r\n\n   - Provides a standard measure of value, making it easier to compare prices.\r\n\n3. **Store of Value**: \r\n\n   - Maintains value over time, allowing individuals to save and defer consumption.\r\n\n### Currency Exchange\r\n\n- **Exchange Rate**: The rate at which one currency can be exchanged for another. It fluctuates based on market conditions.\r\n\n- **Foreign Exchange Market (Forex)**: A global marketplace for trading national currencies against one another.\r\n\n### Importance of Currency\r\n\n- **Economic Stability**: A stable currency promotes trade and investment.\r\n\n- **Inflation Control**: Central banks manage currency supply to control inflation and maintain economic stability.','currencies','dollar','Calculation','1');
INSERT INTO `tools` VALUES ('8','Source Code Viewer','Grab the HTML source code of a given URL or website','','## What is source code?\r\nThe term **source code** refers to the human-readable instructions written in a programming language that define the behavior of a computer program or software application. It serves as the foundation for building executable programs and is typically written in languages like PHP, Python, Java, C++, JavaScript, and many others.\r\n\n### Key Points About Source Code:\r\n\n1. **Human-Readable**: Source code is meant to be understood\n2. **Compilation/Interpretation**: Depending on the language, source code is either compiled (translated into machine code) or interpreted (executed directly by an interpreter).\n3. **Comments**: Programmers use comments within the code to explain the logic, making it easier for others (or themselves) to understand later.\n4. **Version Control**: Source code is often managed using version control systems (like Git), allowing multiple developers to collaborate and track changes.\n5. **Open Source**: Some projects are released as open source, meaning their source code is freely available for anyone to view, modify, and distribute.\n### Example of Simple Source Code\nHere\'s a simple example written in Python that prints "Hello, World!" to the console:\n```python\n# This is a simple Hello World program in Python\ndef hello_world():\r\n\n    print("Hello, World!")\r\n\nhello_world()\r\n\n```\r\n\n### Importance of Source Code\r\n\n- **Collaboration**: Multiple developers can work on the same project, making it easier to share and improve software.\r\n\n- **Maintenance**: Source code allows for easy updates and bug fixes.\r\n\n- **Learning**: Analyzing source code helps new programmers learn coding techniques and best practices.','source-code','code','Programming','1');
INSERT INTO `tools` VALUES ('9','Hash Generator','Generate SHA1, MD5, SHA256 and other hashes of given tools','','## What is a hash?\r\nA **hash** is a function that converts an input (or "message") into a fixed-size string of bytes, typically in a way that is unique to each unique input. Hash functions are commonly used in various applications, including tools integrity verification, password storage, and digital signatures.\r\n\n### Key Characteristics of Hash Functions:\r\n\n1. **Deterministic**: The same input will always produce the same hash output.\n2. **Fixed Size**: Regardless of the size of the input, the output (hash) is always of a fixed length. For example, SHA-256 produces a 256-bit (32-byte) hash.\n3. **Fast Computation**: It should be quick to compute the hash for any given input.\n4. **Preimage Resistance**: It should be infeasible to reverse the process, meaning you cannot easily retrieve the original input from its hash.\n5. **Collision Resistance**: It should be unlikely for two different inputs to produce the same hash output.\n6. **Avalanche Effect**: A small change in the input should produce a significantly different hash.\n### Common Hash Algorithms:\n- **MD5**: Produces a 128-bit hash; widely used but considered insecure for cryptographic purposes due to vulnerabilities.\n- **SHA-1**: Produces a 160-bit hash; also considered insecure due to found vulnerabilities.\n- **SHA-256**: Part of the SHA-2 family, produces a 256-bit hash, widely used for secure applications.\n- **SHA-3**: The latest member of the Secure Hash Algorithm family, offering different output sizes.\n### Applications of Hash Functions:\n1. **Data Integrity**: Ensuring that tools has not been altered during transmission. Hashes can be compared to verify integrity.\n2. **Password Storage**: Storing hashed versions of passwords instead of plain text for security.\n3. **Digital Signatures**: Ensuring authenticity and integrity of messages.\n4. **Cryptographic Applications**: Used in various security protocols, including TLS/SSL.\r\n','hash','fingerprint','Security','1');
INSERT INTO `tools` VALUES ('10','SSL Checker','Check information regarding an SSL Certificate of a domain','','## What is an SSL certificate?\r\n\nAn SSL (Secure Sockets Layer) certificate is a digital certificate that authenticates the identity of a website and enables an encrypted connection. Here are some key points about SSL certificates:\r\n\n### Purpose\n- **Encryption**: SSL certificates encrypt tools transmitted between the user’s browser and the web server, ensuring confidentiality and tools integrity.\n- **Authentication**: They verify the identity of the website, helping to prevent attacks like phishing.\n### Types of SSL Certificates\n1. **Domain Validated (DV)**: Basic validation, confirming ownership of the domain.\n2. **Organization Validated (OV)**: Includes verification of the organization, providing more trust.\n3. **Extended Validation (EV)**: Offers the highest level of validation, displaying the organization’s name in the browser\'s address bar.\n### How to Obtain an SSL Certificate\n1. **Choose a Certificate Authority (CA)**: Select a trusted CA to purchase your SSL certificate.\n2. **Generate a CSR**: Create a Certificate Signing Request (CSR) on your server.\n3. **Submit the CSR**: Send it to your chosen CA along with the necessary documentation for validation.\n4. **Install the Certificate**: Once issued, install the SSL certificate on your web server.\n### Benefits\n- **Enhanced Security**: Protects sensitive information such as login credentials and payment details.\n- **SEO Advantage**: Search engines may rank secure sites higher.\n- **User Trust**: Users are more likely to trust websites with SSL certificates, indicated by a padlock icon in the browser.\n### Conclusion\nImplementing an SSL certificate is essential for maintaining security and trust for any website, especially those handling sensitive information.','ssl-check','lock','Security','1');
INSERT INTO `tools` VALUES ('18','URL Shortener','Shorten long URLs quickly and obtain a much shorter URL','','## What is a URL?\r\n\nA URL, or Uniform Resource Locator, is a specific type of Uniform Resource Identifier (URI) that provides a means to access a resource on the internet. Here are the main components and features of a URL:\r\n\n1. **Protocol**: This indicates the method used to access the resource. Common protocols include:\r\n\n   - `http://` (Hypertext Transfer Protocol)\r\n\n   - `https://` (HTTP Secure)\r\n\n   - `ftp://` (File Transfer Protocol)\r\n\n2. **Domain Name**: This is the human-readable address of the website, such as `www.example.com`. It identifies the server that hosts the resource.\r\n\n3. **Port (optional)**: This number can specify a particular port on the server. If omitted, the default ports are used (80 for HTTP and 443 for HTTPS). For example, `:8080` might be included in a URL if a non-standard port is being used.\r\n\n4. **Path**: This indicates the specific location of a resource on the server. For example, `/folder/page.html` points to a specific HTML page within a directory.\r\n\n5. **Query String (optional)**: This is used to pass parameters to the server, often seen in search queries. It starts with a `?` and can include multiple parameters separated by `&`. For example: `?search=keyword&sort=ascending`.\r\n\n6. **Fragment (optional)**: This is used to navigate to a specific part of a webpage and starts with a `#`. For example, `#section1` would take the user to a specific section of the page.\r\n\n### Example of a URL\r\n\n```\r\n\nhttps://www.example.com:443/folder/page.html?search=keyword#section1\r\n\n```\r\n\nIn this example:\r\n\n- **Protocol**: `https`\r\n\n- **Domain Name**: `www.example.com`\r\n\n- **Port**: `443` (optional and often omitted)\r\n\n- **Path**: `/folder/page.html`\r\n\n- **Query String**: `?search=keyword`\r\n\n- **Fragment**: `#section1` \r\n\nURLs are essential for navigating the web, as they provide the addresses needed to locate resources.\r\n\n### Note\r\n\nURLs shortened here expire in 30 days. However, each visit extends the URL expiration by another 30 days!','short-url','scissors','Programming','1');
INSERT INTO `tools` VALUES ('20','HEX to RGB Converter','Convert Hexadecimal(HEX) color code to RGB(Red Green Blue) code','','### About HEX and RGB\r\n**HEX** and **RGB** are both ways to represent colors, but they use different systems.\r\n\n**HEX** uses six hexadecimal digits (0-9 and A-F) to represent the intensity of red, green, and blue in a color. #FF0000 represents full red (FF), no green (00), and no blue (00).\r\n\n**RGB** uses three decimal numbers (0-255) to represent the intensity of red, green, and blue. 255 is the highest intensity, while 0 is the lowest. So (255, 0, 0) means full red, no green, and no blue.\r\n\n#### HEX:\r\n\n- Uses six hexadecimal digits (0-9 and A-F).\r\n\n- Each pair of digits represents the intensity of red, green, and blue (e.g., #FF0000 is full red, no green, no blue).\r\n\n- Compact representation, often used in web development.\r\n\n#### RGB:\r\n\n- Uses three decimal numbers (0-255).\r\n\n- Each number represents the intensity of red, green, and blue (e.g., (255, 0, 0) is full red, no green, no blue).\r\n\n- More intuitive for some users, as it uses a familiar decimal system.','hex-to-rgb','','Conversion','1');
INSERT INTO `tools` VALUES ('21','RGB to HEX Converter','Convert RGB(Red Green Blue) color code to HEX(Hexadecimal) color code','','\r\n### About HEX and RGB\r\n**HEX** and **RGB** are both ways to represent colors, but they use different systems.\r\n\r\n**HEX** uses six hexadecimal digits (0-9 and A-F) to represent the intensity of red, green, and blue in a color. #FF0000 represents full red (FF), no green (00), and no blue (00).\r\n**RGB** uses three decimal numbers (0-255) to represent the intensity of red, green, and blue. 255 is the highest intensity, while 0 is the lowest. So (255, 0, 0) means full red, no green, and no blue.\r\n\r\n#### HEX:\r\n- Uses six hexadecimal digits (0-9 and A-F).\r\n- Each pair of digits represents the intensity of red, green, and blue (e.g., #FF0000 is full red, no green, no blue).\r\n- Compact representation, often used in web development.\r\n\r\n#### RGB:\r\n- Uses three decimal numbers (0-255).\r\n- Each number represents the intensity of red, green, and blue (e.g., (255, 0, 0) is full red, no green, no blue).\r\n- More intuitive for some users, as it uses a familiar decimal system.\r\n\r\n','rgb-to-hex','','Conversion','1');
INSERT INTO `tools` VALUES ('22','Code to Text ratio','Calculate the code to text ratio and percentage of your webpage','','## What is code to text ratio?\r\n\nThe **code to text ratio** is a measure of how much of a webpage\'s source code is dedicated to displaying actual text content versus other elements like HTML tags, scripts, and styling.\r\n\n### Why a Good Code to Text Ratio Matters\r\n\nA good code to text ratio is important for several reasons:\r\n\n- **SEO:** Search engines like Google prioritize pages with valuable text content. A higher ratio often indicates more relevant and engaging content, which can boost your search rankings.\r\n\n- **User Experience:** Pages with a good ratio are typically faster to load and easier to navigate. This improves the overall user experience, making your website more enjoyable to visit.\r\n\n- **Accessibility:** A well-balanced ratio can make your website more accessible to users with disabilities, as it reduces the amount of code that screen readers need to process.\r\n\n### The Ideal Code to Text Ratio\nThe ideal ratio is generally considered to be between 25% and 70%. This means that 25% to 70% of the page should be actual text content, while the rest can be the underlying code.\r\n\n### How to Improve Your Code to Text Ratio\r\n\n- **Reduce Unnecessary Code:** Simplify your HTML by removing unnecessary tags, attributes, and comments.\r\n\n- **Optimize Images:** Use compressed images and ensure they are relevant to the content. Large images can significantly increase your code size.\r\n\n- **Increase Text Content:** Add more valuable text to your pages. This could be through blog posts, articles, or even just expanding on existing content.\r\n\n- **Avoid Excessive Styling:** While CSS is essential, avoid over-using it. Keep your stylesheets clean and efficient.','code-text-ratio','','SEO','1');
INSERT INTO `tools` VALUES ('23','SSL Generator','Generate a self-signed SSL certificate for your website domain','','## What is a self-signed SSL certificate?\r\n\nA **self-signed SSL certificate** is a type of digital certificate that is signed by the entity that created it rather than a trusted certificate authority (CA). Here are some key points about self-signed certificates:\r\n\n### Key Features:\r\n\n1. **Purpose**:\r\n\n   - Self-signed certificates are used to secure communications over the internet, typically for internal use or testing purposes.\r\n\n2. **Creation**:\r\n\n   - They can be generated easily using tools like OpenSSL without the need for a third-party CA.\r\n\n3. **Trust**:\r\n\n   - Browsers and other clients do not trust self-signed certificates by default because they are not issued by a recognized authority. This means users may see warnings when visiting a site that uses a self-signed certificate.\r\n\n4. **Cost**:\r\n\n   - Self-signed certificates are free to create, as there are no fees associated with acquiring them from a CA.\r\n\n5. **Use Cases**:\r\n\n   - Commonly used in development environments, testing, internal networks, or for encrypting communications in applications where trust is managed internally.\r\n\n6. **Limitations**:\r\n\n   - Since they are not trusted by default, they are not suitable for production environments where security and user trust are critical. Users may need to manually accept the certificate to proceed.\r\n\n### Summary:\r\n\nWhile self-signed SSL certificates can provide encryption, they do not offer the same level of trust and validation that certificates from recognized CAs do. For public-facing websites, it’s generally recommended to obtain a certificate from a trusted CA to ensure security and user confidence.','ssl-generator','lock','Security','1');
INSERT INTO `tools` VALUES ('30','Website Screenshot Generator','Capture a screenshot of a webpage','','## Note\r\nUse this tool to capture a screenshot of a website','website-screenshot','','Miscellaneous','1');
INSERT INTO `tools` VALUES ('31','HTTP Headers Viewer','View HTTP Header information of a webpage','','## What are HTTP Headers?\r\nHTTP headers are key-value pairs sent in HTTP requests and responses that provide essential information about the request or the response. They play a crucial role in communication between clients (like web browsers) and servers. Here\'s a breakdown of some key aspects:\r\n\n### Types of HTTP Headers\r\n\n1. **Request Headers**: Sent by the client to provide information about the request.\r\n\n   - **Examples**:\r\n\n     - `Accept`: Specifies the media types that are acceptable for the response.\r\n\n     - `User-Agent`: Contains information about the user agent (browser or client) making the request.\r\n\n     - `Authorization`: Contains credentials for authenticating the client with the server.\r\n\n2. **Response Headers**: Sent by the server to provide information about the response.\r\n\n   - **Examples**:\r\n\n     - `Content-Type`: Indicates the media type of the resource being sent.\r\n\n     - `Set-Cookie`: Used to send cookies from the server to the client.\r\n\n     - `Cache-Control`: Directives for caching mechanisms in both requests and responses.\r\n\n3. **General Headers**: Can be used in both requests and responses but do not relate to the content.\r\n\n   - **Examples**:\r\n\n     - `Date`: Represents the date and time at which the message was sent.\r\n\n     - `Connection`: Control options for the current connection.\r\n\n### Importance of HTTP Headers\r\n\n- **Control Data Transfer**: Headers can control how tools is sent and received, determine caching behavior, and set content types.\r\n\n- **Authentication and Security**: Headers are often used for authentication, such as tokens and session management.\r\n\n- **Content Negotiation**: They help in determining the format of the response based on client capabilities.\r\n\n### Example of HTTP Request and Response\r\n\n**Sample HTTP Request:**\r\n\n```\r\n\nGET /index.html HTTP/1.1\r\n\nHost: www.example.com\r\n\nUser-Agent: Mozilla/5.0\r\n\nAccept: text/html\r\n\n```\r\n\n**Sample HTTP Response:**\r\n\n```\r\n\nHTTP/1.1 200 OK\r\n\nContent-Type: text/html; charset=UTF-8\r\n\nContent-Length: 1234\r\n\nDate: Sat, 12 Jan 2025 12:00:00 GMT\r\n\n<html>\r\n\n  <body>\r\n\n    <h1>Hello, World!</h1>\r\n\n  </body>\r\n\n</html>\r\n\n```\r\n\nIn summary, HTTP headers are vital for controlling the behavior of HTTP requests and responses, providing necessary context and instructions for both clients and servers.','http-headers','','Programming','1');
INSERT INTO `tools` VALUES ('32','ROT13,18,47 Encoding and Decoding','Encode/Decode text in ROT13,18 and 47','','## What is ROT13, ROT18 or ROT47?\r\n\n### ROT13\r\n\n- **Definition**: ROT13 is a simple letter substitution cipher that replaces each letter with the letter 13 positions later in the alphabet. It wraps around such that after \'Z\', it continues from \'A\'.\r\n\n- **How It Works**: \r\n\n  - For example:\r\n\n    - A ↔ N\r\n\n    - B ↔ O\r\n\n    - C ↔ P\r\n\n    - ...\r\n\n    - M ↔ Z\r\n\n- **Common Uses**: \r\n\n  - Often used in online forums to obscure spoilers or sensitive information.\r\n\n  - Easy to implement and symmetric, meaning encoding and decoding are the same operation.\r\n\n### ROT18\r\n\n- **Definition**: ROT18 extends the concept of ROT13 by shifting letters by 18 positions in the alphabet and digits by 8 positions (0-9).\r\n\n- **How It Works**: \r\n\n  - For letters:\r\n\n    - A ↔ S\r\n\n    - B ↔ T\r\n\n    - ...\r\n\n    - I ↔ W\r\n\n  - For digits:\r\n\n    - 0 ↔ 8\r\n\n    - 1 ↔ 9\r\n\n    - 2 ↔ 0\r\n\n    - ...\r\n\n- **Common Uses**: \r\n\n  - Less common than ROT13 but can be used to obscure text while providing a different level of obfuscation.\r\n\n### ROT47\r\n\n- **Definition**: ROT47 shifts printable ASCII characters (from 32 to 126) by 47 positions. This includes letters, digits, and various symbols.\r\n\n- **How It Works**: \r\n\n  - For example, if you apply ROT47 to the character `!`, which has an ASCII value of 33, it shifts to ASCII value 80, resulting in the character `P`.\r\n\n  - The rotation wraps around after reaching the maximum printable ASCII character.\r\n\n- **Common Uses**: \r\n\n  - Used in some programming languages and applications to obscure text or code snippets.\r\n\n  - Provides a way to encode all printable characters, making it more versatile than just shifting alphabetic characters.\r\n\n> Each of these rotation algorithms provides a different method of encoding text, with varying levels of complexity and application.','rot','','Programming','1');
